/* @lc app=leetcode id=1938 lang=kotlin */ class Solution { fun maxGeneticDifference(parents: IntArray, queries: Array<IntArray>): IntArray = parents.size.let { n -> Array(n) { ArrayList<Int>() }.also { g -> parents.forEachIndexed { i, p -> if (p >= 0) g[p].add(i) } }.let { g -> queries.indices.groupBy { queries[it][0] }.let { qs -> IntArray(queries.size).let { ans -> IntArray(1 shl 19).let { cnt -> IntArray(n).let { par -> java.util.ArrayDeque<IntArray>().also { it.addFirst(intArrayOf(parents.indexOf(-1), -1, 0)) }.let { st -> (sequenceOf(parents.indexOf(-1) * 2) + generateSequence { st.peekFirst()?.let { f -> if (f[2] < g[f[0]].size) g[f[0]][f[2]++].let { v -> st.addFirst(intArrayOf(v, f[0], 0)).let { v * 2 } } else st.pollFirst().let { f[0] * 2 + 1 } } }).forEach { e -> (e / 2).let { v -> (if (e % 2 == 0) 1 else -1).let { s -> (1..18).forEach { l -> cnt[(1 shl l) + (v shr (18 - l))] += s } }.let { if (e % 2 == 0) qs[v].orEmpty().forEach { qi -> (1..18).fold(0 to 0) { (pre, res), l -> (queries[qi][1] shr (18 - l) and 1 xor 1).let { want -> if (cnt[(1 shl l) + (pre shl 1 or want)] > 0) (pre shl 1 or want) to (res or (1 shl (18 - l))) else (pre shl 1 or (want xor 1)) to res } }.let { ans[qi] = it.second } } } } } }.let { ans } } } } } } } }